const fs = require('node:fs');
const path = require('node:path');
const root = path.resolve(__dirname, '..');
const file = path.join(root, 'data.json');
const data = JSON.parse(fs.readFileSync(file, 'utf8'));
const review = 'chem-6-8';
const fresh = [];
const h = 6.626e-34, c = 3.00e8;
const fixed = (x, n=2) => x.toFixed(n);
function add(id, section, title, body, result, why, options={}) {
  const q = {id,review,section,title,body:Array.isArray(body)?body:[body],kind:'frq',practiceSet:'chem-class',difficulty:'Class practice',answer:{blocks:[result,`Why: ${why}`]},...options};
  q.answer.text = q.answer.blocks.join(' ');
  fresh.push(q); return q;
}
function six(n,title,body,result,why,options) {return add(`C6-${n}`, 'CHEM 6',title,body,result,why,options);}
function seven(n,title,body,result,why,options) {return add(`C7-${n}`, 'CHEM 7',title,body,result,why,options);}
function eight(n,title,body,result,why,options) {return add(`C8-${n}`, 'CHEM 8',title,body,result,why,options);}
const guided = (chain,step,hint) => ({practiceSet:'chem-learn',difficulty:'Guided connection',chain,step,hint});
const mc = (choices,correct,multiple=false) => ({kind:'conceptual',choices,correctChoices:correct,multiple});
// Quiz 2 skills appear in a clearly labeled prerequisite section.
data.topics['CHEM foundations']='Prerequisites · Solutions & stoichiometry';
function foundation(n,title,body,result,why,opts={}) {return add(`CF-${String(n).padStart(2,'0')}`,'CHEM foundations',title,body,result,why,{practiceSet:'chem-foundations',difficulty:'Prerequisite refresher',...opts});}
foundation(1,'From formula units to an ion picture','A particle model of dissolved MgCl₂ contains 4 Mg²⁺ ions. How many Cl⁻ ions must it contain, and should the ions be joined in MgCl₂ clusters or dispersed? Assume complete dissolution.','8 Cl⁻ ions; dispersed ions.','Each formula unit supplies two chlorides per magnesium. Dissociation preserves the 1:2 count and total charge, but separates the ions.');
foundation(2,'Ion molarity is not salt molarity','A solution is 0.180 M CaBr₂. Give [Ca²⁺], [Br⁻], and the total molar concentration of dissolved ions.','0.180 M; 0.360 M; 0.540 M.','CaBr₂ → Ca²⁺ + 2 Br⁻. Multiply salt molarity by each ion coefficient, then add the ion concentrations.');
foundation(3,'Prepare a target chloride concentration','Prepare 250.0 mL with [Cl⁻] = 0.240 M using ZnCl₂ (136.29 g/mol). What mass of ZnCl₂ is required? Round to 2 decimal places.','4.09 g.','0.240 × 0.2500 = 0.0600 mol Cl⁻; divide by 2 to obtain 0.0300 mol ZnCl₂, then multiply by 136.29. Using chloride moles directly doubles the mass.');
foundation(4,'Dilution preserves moles, not concentration','Dilute 20.0 mL of 0.300 M AlCl₃ to a final volume of 150.0 mL. Find the final [Cl⁻].','0.120 M.','Initial chloride moles = 3 × 0.300 × 0.0200 = 0.0180 mol. Divide by the final 0.1500 L, not the added water volume.');
foundation(5,'Work backward through percent yield','For 2 Al + 3 Cl₂ → 2 AlCl₃, what mass of Al (26.98 g/mol) is needed to obtain 40.0 g AlCl₃ (133.33 g/mol) at 80.0% yield? Cl₂ is in excess. Round to 2 decimal places.','10.12 g.','Required theoretical product = 40.0/0.800 = 50.0 g. The Al:AlCl₃ mole ratio is 1:1, so use (50.0/133.33) × 26.98.');
foundation(6,'Balance oxygen after carbon and hydrogen','Balance the complete combustion of C₂H₆O to CO₂ and H₂O using the smallest whole-number coefficients. Give the coefficient of O₂.','1 C₂H₆O + 3 O₂ → 2 CO₂ + 3 H₂O; O₂ coefficient = 3.','The products contain 7 oxygen atoms per fuel molecule; the fuel already supplies 1, so only 6 oxygen atoms must come from O₂.');
foundation(7,'Neutralization counts equivalents','What volume of 0.250 M H₂SO₄ neutralizes 30.0 mL of 0.400 M NaOH? Assume both acidic protons react completely. Round to 1 decimal place in mL.','24.0 mL.','H₂SO₄ + 2 NaOH → Na₂SO₄ + 2 H₂O. Divide 0.0120 mol NaOH by 2, then divide by 0.250 M. Equal moles of acid and base are not required.');
foundation(8,'Keep a weak acid together','NaOH(aq) reacts with weak acid HCN(aq) to form NaCN(aq) and water. Identify the spectator ion and write the net ionic equation.','Spectator: Na⁺. HCN(aq) + OH⁻(aq) → CN⁻(aq) + H₂O(l).','Split the strong base and soluble salt, but leave the weak acid molecular. CN⁻ is produced by reaction, so it is not a spectator.');
foundation(9,'Separate formula writing from solubility','Mix aqueous Na₂CO₃ and Ca(NO₃)₂. Given that calcium carbonate is insoluble and sodium salts and nitrates are soluble, name the precipitate and write the balanced molecular equation.','CaCO₃(s). Na₂CO₃(aq) + Ca(NO₃)₂(aq) → CaCO₃(s) + 2 NaNO₃(aq).','Ca²⁺ and CO₃²⁻ form a neutral 1:1 solid. Na⁺ and NO₃⁻ remain dissolved; solubility does not mean they disappear.');
foundation(10,'The smaller mole amount need not limit','For Cu(NO₃)₂ + 2 NaOH → Cu(OH)₂ + 2 NaNO₃, mix 40.0 mL of 0.500 M Cu(NO₃)₂ with 60.0 mL of 0.500 M NaOH. Find the limiting reactant and precipitate mass (97.56 g/mol). Round to 2 decimal places.','NaOH; 1.46 g Cu(OH)₂.','Cu²⁺ can make 0.0200 mol solid, but 0.0300 mol OH⁻ can make only 0.0150 mol solid. Compare product capacity using the coefficients.');
foundation(11,'Subtract what reacts','For N₂ + 3 H₂ → 2 NH₃, start with 2.40 mol N₂ and 5.10 mol H₂. Which reactant remains, and how many moles? Round to 2 decimal places.','N₂ remains; 0.70 mol.','H₂ limits and consumes 5.10/3 = 1.70 mol N₂. Excess remaining = 2.40 − 1.70; it is not the initial amount of excess reactant.');
foundation(12,'Count particles after dilution','A soluble salt is a strong electrolyte. Its 0.100 M solution is diluted to twice its original volume. Which statement is correct?','B. Ion concentrations halve; dissolved ion counts stay the same.','Adding solvent changes volume without changing dissolved solute moles, assuming no reaction or loss.',mc(['Ion counts double and concentrations stay the same.','Ion concentrations halve; dissolved ion counts stay the same.','The ions recombine into neutral salt molecules.','Both counts and concentrations halve.'],[1]));
// Chapter 6: scaffold a chain, then transfer to quiz-style tasks.
six(21,'Light chain 1 · Predict before calculating','Light A has wavelength 420 nm; light B has wavelength 630 nm. Which has higher frequency and photon energy? Find E(A)/E(B).','A has both; E(A)/E(B) = 1.50.','At constant c, frequency and energy vary as 1/λ. Reverse the wavelength ratio: 630/420.',guided('Light → electron response',1,'Write E = hc/λ. Which quantity becomes larger when the denominator shrinks?'));
six(22,'Light chain 2 · Convert a wavelength','A 420 nm photon strikes a detector. Use h = 6.626 × 10⁻³⁴ J·s and c = 3.00 × 10⁸ m/s. Calculate its energy in J to 3 significant figures.','4.73 × 10⁻¹⁹ J.','420 nm = 4.20 × 10⁻⁷ m; E = hc/λ. The ratio prediction in C6-21 and this numerical result describe the same inverse relationship.',guided('Light → electron response',2,'Convert nm to m before substituting. Check that J·s × m/s divided by m gives J.'));
six(23,'Light chain 3 · Spend energy to eject an electron','A metal has work function 3.20 × 10⁻¹⁹ J. A photon carries 4.73 × 10⁻¹⁹ J. Does it eject an electron, and what is Kmax?','Yes; 1.53 × 10⁻¹⁹ J.','The work function is the fixed energy cost of escape. The remaining photon energy becomes electron kinetic energy: Kmax = E − φ.',guided('Light → electron response',3,'Compare the photon energy with the work function before subtracting.'));
six(24,'Light chain 4 · Change brightness','For the same metal, 420 nm light ejects electrons. Its intensity is doubled without changing wavelength. Predict the changes in maximum electron kinetic energy and the number emitted per second in the ordinary single-photon model.','Kmax unchanged; the emission rate increases (ideally doubles with unchanged collection efficiency).','Each photon still carries hc/λ and pays the same work function. Brighter light delivers more photons rather than more energy per photon.',guided('Light → electron response',4,'Separate energy per photon from photons arriving per second.'));
six(25,'Capacity chain 1 · What does 4d identify?','For a 4d subshell, give n, ℓ, allowed mℓ values, number of orbitals, and maximum electrons.','n = 4; ℓ = 2; mℓ = −2, −1, 0, +1, +2; 5 orbitals; 10 electrons.','The letter sets ℓ, then mℓ has 2ℓ+1 possibilities. Each orbital holds two opposite-spin electrons.',guided('Quantum numbers → occupancy',1,'d always means ℓ = 2, independent of the leading shell number.'));
six(26,'Capacity chain 2 · Leave ℓ unspecified','In one atom, what is the maximum number of electrons with n = 4 and mℓ = 0? Then restrict mₛ to +½.','8 electrons; with mₛ = +½, 4 electrons.','The 4s, 4p, 4d, and 4f subshells each contain one mℓ = 0 orbital. Two spins per orbital give 8; one allowed spin gives 4.',guided('Quantum numbers → occupancy',2,'List every allowed ℓ, then check whether each has an mℓ = 0 orbital.'));
six(27,'Capacity chain 3 · Capacity versus population','The 3d subshell can hold 10 electrons. Neutral Sc (Z = 21) has [Ar] 4s²3d¹. How many 3d electrons are present, and how many more could that subshell hold?','1 present; room for 9 more.','Capacity follows the number of orbitals; actual population follows the atom’s electron count and ground-state configuration.',guided('Quantum numbers → occupancy',3,'Do not replace an actual exponent by a subshell’s maximum capacity.'));
six(28,'Atom chain 1 · Decode selenium','Se (Z = 34) has [Ar] 3d¹⁰4s²4p⁴. Give its valence count, number of unpaired electrons, magnetic behavior, and ℓ for a highest-energy occupied electron.','6 valence electrons; 2 unpaired; paramagnetic; ℓ = 1 (4p).','The outer n = 4 shell has 2 + 4 electrons. Hund’s p⁴ diagram is [↑↓][↑][↑], leaving two unpaired.',guided('Configuration → ion → trend',1,'Fill the three p orbitals singly before pairing the fourth electron.'));
six(29,'Atom chain 2 · Add charge carefully','Se has Z = 34; Br has Z = 35. Give the electron counts of Se²⁻ and Br⁻, determine whether their ground-state configurations match, and identify the larger ion.','Both have 36 electrons and [Kr]; Se²⁻ is larger.','Negative charge adds electrons. In this isoelectronic pair, Se has fewer protons pulling on the same electron configuration.',guided('Configuration → ion → trend',2,'Electron count = Z − signed charge. Compare nuclear charges only after confirming equal electron counts.'));
six(30,'Atom chain 3 · Compare neutral atoms','Which is larger, neutral Se or neutral Br? Which generally has higher first ionization energy? Explain using nuclear attraction across period 4.','Se is larger; Br has higher IE₁.','Across this pair, valence electrons occupy the same shell while nuclear attraction increases, shrinking the atom and making removal harder.',guided('Configuration → ion → trend',3,'Use the neutral atom trend here; the equal-electron rule in C6-29 was for the ions.'));
six(31,'Partial quantum-number capacity','Give maximum electron counts for (a) n = 3, mℓ = +1; (b) n = 3, ℓ = 2, mℓ = −1; (c) n = 3, ℓ = 2, mℓ = −1, mₛ = −½.','(a) 4; (b) 2; (c) 1.','For (a), 3p and 3d each supply one matching orbital. Fixing ℓ and mℓ selects one orbital; fixing spin as well selects one electron.');
six(32,'Invalid is different from empty','Which quantum-number sets could describe an electron? Tuples are (n, ℓ, mℓ, mₛ). Select all that apply.','A and D.','ℓ must be 0…n−1, |mℓ| ≤ ℓ, and mₛ = ±½. B has an unavailable ℓ; C has an unavailable mℓ.',mc(['(3, 2, +2, +½)','(2, 2, 0, −½)','(4, 1, −2, +½)','(1, 0, 0, −½)'],[0,3],true));
six(33,'Ground, excited, or impossible?','Classify these configurations: A [Ne]3s²3p²; B [Ne]3s¹3p³; C [Ne]3s³3p¹. Assume neutral atoms.','A ground-state Si; B excited-state Si; C impossible.','All have 14 electrons. Moving an electron to a higher subshell can give an allowed excited state, but an s orbital cannot hold three electrons.');
six(34,'Match hydrogen transitions to spectral regions','Starting at n = 5 in H, match transitions 5 → 1, 5 → 2, and 5 → 3 to UV, visible, and IR. Which has the longest wavelength?','5 → 1: UV; 5 → 2: visible; 5 → 3: IR. Longest: 5 → 3.','The final shell identifies these series. The smallest energy drop gives the lowest-energy, longest-wavelength photon.');
six(35,'A nonhydrogen cascade','An atom has E₁ < E₂ < E₃. The 3 → 2 line is 600.0 nm and the 2 → 1 line is 300.0 nm. Find the 3 → 1 wavelength, rounded to 1 decimal place. Do not assume hydrogen energy levels.','200.0 nm.','The gaps add: hc/λ₃₁ = hc/600.0 + hc/300.0, so 1/λ₃₁ = 1/600.0 + 1/300.0. Wavelengths themselves do not add.');
six(36,'Combine or subtract gaps?','For a nonhydrogen atom, the 3 → 1 line is 200.0 nm and the 2 → 1 line is 300.0 nm. Find the 3 → 2 wavelength to 1 decimal place.','600.0 nm.','Subtract the common lower gap: 1/λ₃₂ = 1/200.0 − 1/300.0. The smaller remaining energy corresponds to a longer wavelength.');
six(37,'Infer a threshold from two observations','A metal emits electrons at 480 nm but not at 620 nm. Classify 450, 700, and 550 nm light as certainly ejects, certainly does not, or cannot determine from these data.','450: certainly ejects; 700: certainly does not; 550: cannot determine.','The unknown threshold lies between the tested photon energies. Shorter wavelengths carry more energy; an intermediate wavelength needs more information.');
six(38,'A radio photon and centimeters','A photon has energy 3.00 × 10⁻²⁴ J. Use h = 6.626 × 10⁻³⁴ J·s and c = 3.00 × 10⁸ m/s. Find λ in cm to 2 decimal places.','6.63 cm.','hc/E = 0.06626 m; multiply by 100 cm/m. A radio wavelength should not shrink when converted from meters to centimeters.');
six(39,'Matter wavelength with an artificial mass','A fictional ball has mass 5.00 × 10⁻²⁴ kg and speed 25.0 m/s. Use h = 6.626 × 10⁻³⁴ J·s. Find its de Broglie wavelength in pm to 2 decimal places.','5.30 pm.','λ = h/(mv) = 5.3008 × 10⁻¹² m. Multiply meters by 10¹² to obtain pm.');
six(40,'Same momentum, different particles','An electron and a much heavier particle have equal momentum. Compare their de Broglie wavelengths. If the heavier particle instead had the same speed as the electron, would its wavelength be longer or shorter?','Equal momentum: equal wavelengths. Equal speed: heavier particle has shorter wavelength.','λ = h/p depends on momentum. At the same speed, increasing mass increases p = mv and reduces λ.');
six(41,'Ionization jump identifies a valence count','A period-3 element has successive ionization energies of 738, 1451, 7733, and 10543 kJ/mol. Identify the element and its common monatomic ion.','Mg; Mg²⁺.','The large jump occurs after the second electron, so two valence electrons are removed before a core electron. Period 3, group 2 is Mg.');
six(42,'Transition-metal electron removal','Fe (Z = 26) has [Ar]3d⁶4s². Give configurations for Fe²⁺ and Fe³⁺, and the number of unpaired electrons in each isolated-ion Hund model.','Fe²⁺: [Ar]3d⁶, 4 unpaired. Fe³⁺: [Ar]3d⁵, 5 unpaired.','Remove 4s electrons first because they have the highest n. Fill the five d orbitals singly before pairing; coordination-complex spin effects are excluded.');
six(43,'Even electron counts can be paramagnetic','Neutral S (Z = 16) has 16 electrons. Is it necessarily diamagnetic because this number is even? Give its 3p occupation and unpaired count.','No; 3p⁴ = [↑↓][↑][↑], with 2 unpaired electrons; paramagnetic.','Even total electron count does not guarantee every orbital is paired. Hund’s rule spreads electrons across degenerate orbitals first.');
six(44,'Rank isoelectronic radii','Order O²⁻, F⁻, Na⁺, and Mg²⁺ by increasing ionic radius. Atomic numbers: O 8, F 9, Na 11, Mg 12.','Mg²⁺ < Na⁺ < F⁻ < O²⁻.','All have 10 electrons. More protons pull that same electron cloud inward more strongly.');
six(45,'Which change is absorption?','Choose the one correct statement for H.','C. A 2 → 4 transition absorbs a photon and has positive atomic ΔE.','Going to a higher n raises the atom’s energy, so it must absorb energy. Photon energy is positive for both absorption and emission.',mc(['A 4 → 2 transition absorbs a photon.','A 2 → 4 transition has negative atomic ΔE.','A 2 → 4 transition absorbs a photon and has positive atomic ΔE.','An emitted photon has negative energy.'],[2]));
six(46,'Reading orbital energy is not reading orbital size','Compare 3s, 3p, and 3d energies in (a) H in the course model and (b) a typical multielectron atom. What changes between the models?','(a) Equal. (b) 3s < 3p < 3d.','Electron–electron shielding and differences in penetration split subshell energies in multielectron atoms. In hydrogen the model energy depends only on n.');
// Chapter 7: connect the count to a defensible structure and shape.
seven(19,'Structure chain 1 · Count before drawing','For NH₄⁺, count total valence electrons. Explain whether the positive charge adds or removes an electron from the neutral-atom sum.','8 valence electrons; subtract 1 for the +1 charge.','N contributes 5 and four H atoms contribute 4. A cation has one fewer electron: 5 + 4 − 1 = 8.',guided('NH₄⁺: electrons → geometry',1,'Use valence electrons, not the total atomic electron counts.'));
seven(20,'Structure chain 2 · Place every electron','NH₄⁺ has 8 valence electrons. Draw its Lewis structure, give the central N lone-pair count, and assign the N formal charge.','Four N–H single bonds; no N lone pairs; FC(N) = +1. Each H has FC = 0; enclose the ion in brackets with +.','Four bonds use all 8 electrons. FC(N) = 5 − 0 − 4 = +1; do not add an extra lone pair copied from NH₃.',guided('NH₄⁺: electrons → geometry',2,'Each single bond consumes two of the eight available electrons.'));
seven(21,'Structure chain 3 · The ion differs from NH₃','Compare NH₄⁺ and NH₃ in electron geometry, molecular shape, ideal angle reference, and central-atom hybridization.','Both tetrahedral electron geometry and sp³. NH₄⁺: tetrahedral shape, 109.5°. NH₃: trigonal pyramidal, angle about 107° (less than 109.5°).','Both have four groups around N. NH₃ uses one group for a lone pair; NH₄⁺ uses all four for bonds.',guided('NH₄⁺: electrons → geometry',3,'Count groups first; then omit lone pairs when naming the molecular shape.'));
seven(22,'Resonance chain 1 · A charged electron budget','NO₂⁻ has N central. Count valence electrons and describe one octet Lewis form, including lone pairs.','18 electrons; one N=O and one N–O bond. N has 1 lone pair; double-bonded O has 2; single-bonded O has 3.','5 + 2(6) + 1 = 18. An N=O bond supplies the central octet after lone pairs are placed.',guided('NO₂⁻: resonance → bond properties',1,'After forming the two N–O single bonds and terminal octets, count what remains on N.'));
seven(23,'Resonance chain 2 · Audit the charges','For an NO₂⁻ form with one N=O, one N–O, and one lone pair on N, give FC on N and each type of O. Then state how to get the other equivalent form.','N: 0; double-bonded O: 0; single-bonded O: −1. Move the double bond to the other O while keeping atom positions fixed.','FC = valence − nonbonding electrons − sum of bond orders. The charges total −1 in either form.',guided('NO₂⁻: resonance → bond properties',2,'Count nonbonding electrons individually; a lone pair contains two.'));
seven(24,'Resonance chain 3 · Predict the real bonds','NO₂⁻ has two equivalent resonance forms. How many distinct N–O bond lengths are expected? Give average N–O bond order, central electron geometry, and molecular shape.','One N–O length; bond order 1.5; trigonal planar electron geometry; bent molecular shape.','The equivalent forms share one double bond over two positions: (2 + 1)/2. Two bonded groups plus one N lone pair give three electron groups.',guided('NO₂⁻: resonance → bond properties',3,'The real ion is a delocalized hybrid, not an ion with one permanently single and one permanently double bond.'));
seven(25,'Shape chain 1 · Symmetry requires a drawing','Draw CF₄ and CH₂F₂ with tetrahedral carbon centers. Do polar C–F bonds guarantee a nonzero molecular dipole in both?','No. CF₄ is nonpolar; CH₂F₂ is polar.','Four equivalent C–F dipoles cancel in CF₄. Replacing two F atoms by H destroys that cancellation even though the electron geometry stays tetrahedral.',guided('Shape → polarity → attractions',1,'Compare the surroundings of the central atom, not just the name tetrahedral.'));
seven(26,'Shape chain 2 · Cross the chapter boundary','CF₄ is nonpolar; CH₂F₂ is polar. Which molecular attractions are present in each pure sample? Does either have conventional hydrogen bonding to itself?','CF₄: dispersion. CH₂F₂: dispersion and dipole–dipole. Neither hydrogen-bonds to itself under the N/O/F–H course rule.','Polarity allows permanent dipole attractions. Hydrogen on carbon does not become an H-bond donor merely because the molecule also contains fluorine.',guided('Shape → polarity → attractions',2,'Identify what atom H is directly bonded to.'));
seven(27,'Lewis symbols from a group','Give the number of dots and unpaired dots in a Lewis symbol for P (group 15) and S (group 16), placing one electron on each side before pairing.','P: 5 dots, 3 unpaired dots. S: 6 dots, 2 unpaired dots.','The group gives the valence count. Distribute the first four dots singly on the four sides, then pair the extras.');
seven(28,'Neutral formulas from unequal ion charges','Write the ionic formula formed by Al³⁺ and O²⁻. Give the smallest whole-number ratio of cations to anions.','Al₂O₃; 2:3.','Two aluminum ions give +6 and three oxide ions give −6. Charge neutrality fixes the subscripts; it does not require a 1:1 ratio.');
seven(29,'Lattice attraction without a memorized list','Which has the greater positive lattice-separation energy: NaF or NaI? Both have ±1 ions; F⁻ is smaller than I⁻.','NaF.','With equal charge products, shorter ion-center separation strengthens electrostatic attraction. More energy is needed to separate NaF into gaseous ions.');
seven(30,'Formal charge is electron bookkeeping','In one Lewis form, N has one lone pair and three single bonds. O has three lone pairs and one single bond. Find FC on each. Use N = 5 and O = 6 valence electrons.','FC(N) = 0; FC(O) = −1.','N: 5 − 2 − 3 = 0. O: 6 − 6 − 1 = −1. Subtract nonbonding electrons and bond orders, not just the number of visible lines indiscriminately.');
seven(31,'Keep second-period atoms within an octet','A proposed neutral molecule has carbon with five single bonds and no lone pairs. Is this an allowed expanded-octet carbon structure? Explain.','No.','Five bonds surround carbon with 10 shared electrons. Carbon is a second-period element and does not have an allowed expanded octet in the course Lewis model.');
seven(32,'A multiple bond counts once in VSEPR','CH₂O has H₂C=O connectivity. Give central C electron-group count, molecular geometry, hybridization, and total σ/π bonds.','3 groups; trigonal planar; sp²; 3 σ and 1 π.','The C=O double bond is one spatial group but contains one σ plus one π bond. The two C–H bonds add two σ bonds.');
seven(33,'A lone pair can coexist with a linear shape','XeF₂ has 22 valence electrons. Give central Xe lone pairs, electron geometry, molecular shape, and polarity.','3 lone pairs; trigonal bipyramidal electron geometry; linear molecular shape; nonpolar.','The three lone pairs occupy equatorial positions. The identical F atoms occupy opposite axial positions, so their bond dipoles cancel.');
seven(34,'Four attached atoms need not mean tetrahedral','Compare SF₄ and XeF₄: give central lone pairs and molecular shape for each.','SF₄: 1 lone pair, seesaw. XeF₄: 2 lone pairs, square planar.','The centers have different electron budgets: five groups for S and six for Xe. Count bonds plus lone pairs before selecting geometry.');
seven(35,'Lone-pair placement in five groups','ClF₃ has five electron groups. Where do its two lone pairs sit, and what molecular shape results?','Both equatorial; T-shaped.','Equatorial positions minimize 90° repulsions. The three remaining bonded positions form a T, not a trigonal plane.');
seven(36,'Formal charges distinguish contributors','For fixed N–N–O connectivity in N₂O, compare A: N≡N–O with charges (0,+1,−1) and B: N=N=O with charges (−1,+1,0). Which is preferred, assuming all atoms have octets?','A.','Both have the same charge magnitudes, so placing the negative charge on more electronegative O makes A the better contributor.');
seven(37,'Equivalent resonance is not bond flipping','Select the one accurate description of the two C–O bonds in a carboxylate group with equivalent resonance contributors.','B. The actual bonds have equal intermediate length.','Resonance describes one delocalized electron distribution; the nuclei do not switch between separate single- and double-bond structures.',mc(['One bond is permanently single and one permanently double.','The actual bonds have equal intermediate length.','The molecule alternates rapidly between two atom connectivities.','Each bond has bond order exactly 2.'],[1]));
seven(38,'Read sigma and pi locally','For H–C≡C–H, give each carbon’s hybridization, total σ/π bonds, and C–C–H angle.','Each C: sp; 3 σ, 2 π; 180°.','The triple bond has one σ and two π bonds. Each C–H adds one σ. Each carbon has two electron groups and two unhybridized p orbitals for π bonding.');
seven(39,'Hybrid orbitals do not form the pi bond','Which orbitals form the π bond of the C=C unit in ethene, H₂C=CH₂? How many unhybridized p orbitals remain on each carbon?','Sideways overlap of one unhybridized p orbital from each C; one remains on each.','sp² mixing uses one s and two p orbitals for three hybrid orbitals, leaving one p orbital for the π bond.');
seven(40,'Charge, electron groups, and angle','Give the total valence electrons, electron geometry, molecular shape, and ideal angle reference for H₃O⁺. H contributes 1 and O contributes 6.','8 electrons; tetrahedral electron geometry; trigonal pyramidal shape; tetrahedral reference 109.5°.','6 + 3 − 1 = 8. Three O–H bonds and one lone pair make four groups. The ideal reference is not a claim that the measured angle is exactly 109.5°.');
seven(41,'Energy of bonds versus energy of reaction','For H₂ + Cl₂ → 2 HCl, use D(H–H) = 436, D(Cl–Cl) = 243, and D(H–Cl) = 431 kJ/mol. Estimate ΔH per reaction as written.','−183 kJ/mol of reaction.','Break 436 + 243 = 679 kJ/mol; form 2 × 431 = 862 kJ/mol. ΔH ≈ broken − formed = −183; breaking alone always costs energy.');
seven(42,'Same bond pair, different order','Rank N–N, N=N, and N≡N by increasing bond length. Which requires the most energy to break?','N≡N < N=N < N–N; N≡N requires the most energy.','For the same atom pair, higher bond order generally gives shorter, stronger bonds. Do not apply this rule blindly across unrelated atom pairs.');
seven(43,'Mixed review · Identify a central atom','An unknown neutral main-group atom forms three single bonds to H and retains one lone pair, satisfying an octet. What group is consistent with this, and what shape is predicted?','Group 15; trigonal pyramidal.','For zero formal charge the center needs 2 nonbonding + 3 assigned bonding electrons = 5 valence electrons. Four electron groups with one lone pair give the shape.');
seven(44,'Bond polarity and molecular polarity use different tests','Select every true statement about molecular polarity in the course model.','A, C, D.','Bond polarity depends on electronegativity difference; overall polarity depends on the vector sum in the actual shape.',mc(['A molecule can contain polar bonds and have zero net dipole.','Every molecule with a central lone pair is polar.','Linear COS can be polar because the two bond dipoles need not cancel.','Square-planar XeF₄ is nonpolar despite polar Xe–F bonds.'],[0,2,3],true));
// Chapter 8: structure, interactions, equilibrium, then quantitative transfer.
eight(15,'Attraction chain 1 · Compare equal-mass isomers','Ethanol CH₃CH₂OH and dimethyl ether CH₃OCH₃ have the same formula and molar mass. Which can donate a conventional hydrogen bond? Which can accept one from water?','Only ethanol can donate; both can accept from water.','An O–H bond supplies a donor; an oxygen lone pair supplies an acceptor. Ether has an O atom but no O–H bond.',guided('Structure → IMF → vapor pressure',1,'Check the atom directly attached to H, then check for an available oxygen lone pair.'));
eight(16,'Attraction chain 2 · List all forces','Name every type of molecular attraction present in pure liquid ethanol and pure liquid dimethyl ether under the introductory IMF categories.','Ethanol: dispersion, dipole–dipole, hydrogen bonding. Ether: dispersion and dipole–dipole.','All molecules have dispersion. Both are polar, but only ethanol has the donor needed for hydrogen bonds between identical molecules.',guided('Structure → IMF → vapor pressure',2,'Strongest force and all forces present are different questions.'));
eight(17,'Attraction chain 3 · Infer a measurable property','Between ethanol and dimethyl ether, predict the higher normal boiling point and the lower vapor pressure at a common temperature where their liquid vapor pressures are defined.','Ethanol has the higher normal boiling point and lower vapor pressure.','Their equal molar masses make the extra hydrogen bonding a useful controlling difference: stronger attractions hinder escape and require more heating to boil.',guided('Structure → IMF → vapor pressure',3,'Stronger attractions favor remaining in the liquid.'));
eight(18,'Attraction chain 4 · Diagnose the explanation','A student says ethanol boils higher than ether because boiling breaks its O–H covalent bonds. Correct the explanation.','Boiling overcomes attractions between molecules; ethanol molecules normally retain their O–H bonds.','The higher boiling point reflects stronger intermolecular hydrogen bonding, not breaking the molecule’s intramolecular covalent bonds.',guided('Structure → IMF → vapor pressure',4,'Ask whether the substance has changed chemical identity after vaporization.'));
eight(19,'Equilibrium chain 1 · A closed flask','A sealed flask contains liquid water and its vapor at constant temperature. At equilibrium, is molecular exchange stopped? What two rates are equal?','Exchange continues; evaporation rate equals condensation rate.','Dynamic equilibrium is a balance of ongoing opposing processes, not frozen molecular motion.',guided('Equilibrium → pressure → boiling',1,'A constant macroscopic amount can coexist with continuous molecular exchange.'));
eight(20,'Equilibrium chain 2 · Change the headspace','A pure liquid and vapor are at equilibrium. Headspace volume doubles at fixed temperature, and enough liquid remains. Describe vapor pressure immediately after expansion and after re-equilibration.','Immediately it decreases; eventually it returns to the original saturation vapor pressure.','Expansion initially dilutes the vapor. Net evaporation then increases vapor moles until the fixed-temperature equilibrium pressure is restored.',guided('Equilibrium → pressure → boiling',2,'Distinguish the immediate gas-law response from the later phase-equilibrium response.'));
eight(21,'Equilibrium chain 3 · Pressure sets boiling temperature','A liquid has vapor pressure 250 torr at 40°C and 500 torr at 60°C. Assuming vapor pressure increases smoothly, will its boiling point at external pressure 400 torr lie below 40°C, between 40 and 60°C, or above 60°C?','Between 40°C and 60°C.','Boiling occurs when vapor pressure equals external pressure; 400 torr lies between the two supplied vapor pressures.',guided('Equilibrium → pressure → boiling',3,'Find where P_vap(T) reaches the imposed pressure; no interpolation formula is needed for a bound.'));
eight(22,'Equilibrium chain 4 · Do not redefine normal','The same liquid boils at 60°C under 500 torr. Is 60°C its normal boiling point? Predict whether its normal boiling point is higher or lower.','No; the normal boiling point is higher.','Normal means 760 torr. A higher vapor pressure requires a higher temperature for this liquid.',guided('Equilibrium → pressure → boiling',4,'The word normal specifies the pressure, not the location of the sample.'));
eight(23,'Hydrogen bonding needs the right hydrogen','Which pure substances have conventional intermolecular hydrogen bonding? Select all: CH₃NH₂, CH₃OCH₃, HF, CH₄.','A and C.','CH₃NH₂ has N–H donors and a lone pair; HF has H–F. Ether can accept from water but lacks a donor to hydrogen-bond to itself.',mc(['CH₃NH₂','CH₃OCH₃','HF','CH₄'],[0,2],true));
eight(24,'Polar bonds can cancel before forces are assigned','For pure BF₃ and pure NF₃, identify molecular shape, polarity, and whether permanent dipole–dipole attractions occur.','BF₃: trigonal planar, nonpolar, no permanent dipole–dipole. NF₃: trigonal pyramidal, polar, dipole–dipole present.','BF₃ cancels three equal bond dipoles; NF₃ has a lone pair and a different shape. Both still have dispersion, and neither has H-bond donors.');
eight(25,'A nonpolar substance still attracts its neighbors','Why does Br₂ generally boil higher than Cl₂ even though both are nonpolar?','Br₂ has a larger, more polarizable electron cloud and stronger dispersion.','Nonpolar means no permanent molecular dipole; it does not mean no intermolecular attractions.');
eight(26,'Branching changes contact','Two C₆H₁₄ isomers are nonpolar. One is an extended chain, the other more compact and branched. Which generally has the higher boiling point, and why is equal molar mass not enough?','The extended-chain isomer generally boils higher.','Its shape permits greater intermolecular contact and stronger dispersion. Equal electron counts do not guarantee equal contact geometry.');
eight(27,'Read data at the same temperature','At 35°C, liquids A, B, and C have vapor pressures 90, 180, and 360 torr, respectively. Rank their attraction strengths as inferred from these data. Which is most volatile?','Inferred attraction strength: A > B > C. Most volatile: C.','At the same temperature, easier escape gives higher vapor pressure and indicates weaker overall attractions in this introductory comparison.');
eight(28,'Do not compare vapor pressures at unlike temperatures','Liquid A reaches 300 torr at 20°C; liquid B reaches 300 torr at 50°C. In the usual course comparison, which has stronger attractions and higher normal boiling point?','B.','B needs more heating to reach the same vapor pressure. Comparing the temperature needed for equal pressure is more informative than comparing unlike-temperature pressures directly.');
eight(29,'Read a vapor-pressure table','A liquid has vapor pressures of 100 torr at 20°C, 240 at 40°C, 500 at 60°C, and 760 at 75°C. At external pressure 240 torr, what is its boiling temperature? What is its normal boiling point?','40°C; 75°C.','Read the temperature where vapor pressure matches the specified external pressure. For the normal point, use 760 torr.');
eight(30,'Which side of the boiling boundary?','At 50°C, a substance has saturation vapor pressure 350 torr. Assume only liquid and gas compete at these conditions, below the critical temperature. Classify the stable bulk phase at (a) 500 torr and (b) 200 torr.','(a) Liquid; (b) gas.','At a fixed temperature, pressure above the liquid–vapor boundary favors the denser liquid; below it favors vapor. At exactly 350 torr the phases can coexist.');
eight(31,'When the liquid is all gone','A closed flask initially contains a pure liquid and vapor. After a large isothermal expansion, all the liquid evaporates. Must the final pressure still equal the saturation vapor pressure?','No; it may be below saturation.','Once no liquid reservoir remains, the fixed amount of gas follows its equation of state. The two-phase equilibrium condition no longer fixes its pressure.');
eight(32,'Force category at an ion–water boundary','Which end of water points toward Ca²⁺? Which points toward Cl⁻? Name the attraction in each case.','O end toward Ca²⁺; H ends toward Cl⁻; ion–dipole attractions.','Water has partial negative charge near O and partial positive charge near H. Opposite charges orient toward one another.');
eight(33,'Sort phase-change signs','Classify condensation, sublimation, freezing, and vaporization as endothermic or exothermic for the substance.','Condensation exothermic; sublimation endothermic; freezing exothermic; vaporization endothermic.','Separating particles into a less condensed phase requires energy; the reverse process releases it.');
eight(34,'Latent heat uses moles','How much heat is required to melt 36.0 g of a substance at its melting point? M = 18.0 g/mol; ΔHfus = 6.00 kJ/mol.','12.0 kJ absorbed.','Convert mass to 2.00 mol, then use q = nΔHfus. The units kJ/mol require moles rather than grams.');
eight(35,'A heating plateau has a particle explanation','A pure solid melts at constant pressure while both solid and liquid remain. Heat continues to enter. What happens to temperature, average kinetic energy, and the fraction melted?','Temperature and average kinetic energy stay approximately constant; the fraction melted increases.','Latent heat changes particle arrangement and potential energy instead of raising temperature during the equilibrium plateau.');
eight(36,'Clausius–Clapeyron · Predict pressure','A liquid has P₁ = 100.0 torr at 300.0 K and constant ΔHvap = 30.00 kJ/mol. Use R = 8.314 J/(mol·K) to find P₂ at 320.0 K. Round to 1 decimal place in torr.',`${fixed(100*Math.exp(30000/8.314*(1/300-1/320)),1)} torr.`,'ln(P₂/100.0) = (30000/8.314)(1/300.0 − 1/320.0). Exponentiate to obtain P₂. The warmer sample must have higher vapor pressure.');
eight(37,'Clausius–Clapeyron · Find a temperature','A liquid has P₁ = 200.0 torr at 300.0 K and constant ΔHvap = 35.00 kJ/mol. At what temperature in °C will its vapor pressure be 400.0 torr? R = 8.314 J/(mol·K). Round to 1 decimal place.',`${fixed(1/(1/300-8.314/35000*Math.log(2))-273.15,1)}°C.`,'Use 1/T₂ = 1/300.0 − (8.314/35000) ln(2). Take the reciprocal before subtracting 273.15; the result must exceed 26.85°C.');
eight(38,'Clausius–Clapeyron · Read a slope','A graph of ln(P) versus 1/T has slope −4200 K. Find ΔHvap in kJ/mol using R = 8.314 J/(mol·K). Round to 1 decimal place.','34.9 kJ/mol.','Slope = −ΔHvap/R, so ΔHvap = 4200 × 8.314 = 34918.8 J/mol. The negative slope is consistent with vapor pressure rising as temperature rises.');
eight(39,'Below the triple-point pressure','A substance has triple-point pressure 4.0 atm. At 1.0 atm its solid is warmed through the solid–gas boundary. What phase change occurs, and can a stable liquid appear on this isobar?','Sublimation; no stable equilibrium liquid.','Below the triple-point pressure, the liquid region is inaccessible. Heating crosses directly from solid to gas.');
eight(40,'Above the critical point','A substance has Tc = 35°C and Pc = 80 atm. Classify it at 45°C and 100 atm. Can compression at 45°C create a distinct ordinary liquid–gas interface?','Supercritical fluid; no.','Both critical coordinates are exceeded. Above Tc, pressure alone cannot restore the ordinary liquid–vapor coexistence boundary.');
// Brief reasoning is added to every existing chemistry answer without changing its ID.
const reasons = {
 'C6-01':'Use ν = c/λ and E = hν, then N = Pt/E. Multiplying energy per photon by Nₐ gives energy per mole; mW must become W.',
 'C6-02':'Subtract Kmax from hc/λ to get φ. The longest ejecting wavelength is hc/φ; at the new wavelength use v = √[2(hc/λ − φ)/m].',
 'C6-03':'At fixed wavelength, intensity changes photon arrival rate. At equal power, lower-energy photons arrive in greater number. Only a frequency change alters Kmax for this metal.',
 'C6-04':'Calculate each gap from Eₙ = −RH/n² and use λ = hc/|ΔE|. The emitted energies add to the absorbed energy, but their wavelengths do not.',
 'C6-05':'Insert the line energy hc/λ into RH(1/2² − 1/nᵢ²). Atomic ΔE is negative on emission; the shorter wavelength has greater photon energy.',
 'C6-06':'Ionization from n = 3 requires RH/9 per atom. Multiply by 0.2500Nₐ for the sample. A 900 nm photon is less energetic than the threshold photon.',
 'C6-07':'Use v = √(2K/m), then λ = h/(mv). Speed scales as √K, so quadrupling K doubles v and halves λ.',
 'C6-08':'Convert 0.800% to 0.00800, multiply by speed to get Δv, and use Δx ≥ h/(4πmΔv). Reducing Δv fourfold increases the minimum Δx fourfold.',
 'C6-09':'Apply ℓ ≤ n−1, |mℓ| ≤ ℓ, and mₛ = ±½ independently. Valid ℓ values 2 and 3 identify d and f subshells.',
 'C6-10':'Count all matching orbitals, then multiply by the permitted spins. For mℓ = 0, each allowed subshell contributes one orbital; n = 2 has no d subshell.',
 'C6-11':'A p subshell has three orbitals, d has five, and shell n has n². Nodes follow n−1; shielding and penetration split equal-n energies only in multielectron atoms.',
 'C6-12':'Hund concerns filling degenerate orbitals; Pauli forbids identical spins in one orbital; Aufbau describes ground-state energy order. A p⁴ subshell pairs only after three singly occupied orbitals.',
 'C6-13':'Use the Cr and Cu ground-state exceptions, then remove 4s before 3d electrons to form cations. Any unpaired electron makes the isolated species paramagnetic.',
 'C6-14':'The outer 4s²4p³ shell gives five valence electrons and three unpaired p electrons. Both anions reach 36 electrons; fewer protons make As³⁻ larger.',
 'C6-15':'Remove 5p electrons before 5s. Sn²⁺ retains the 5s² pair; Sn⁴⁺ retains a filled 4d subshell. Both arrangements contain only paired electrons.',
 'C6-16':'Use proton count only after checking equal electron counts. Across period 4 radius decreases; removing electrons contracts a cation, while electron addition expands an anion.',
 'C6-17':'The jump after IE₃ indicates three valence electrons. The total for Al³⁺ is 0.125(578 + 1817 + 2745) kJ. Subshell energy and pairing explain the two IE₁ exceptions.',
 'C6-18':'Add signed energy changes: 496 − 349 = +147. Adding an electron to an anion costs energy; forming a lattice can release enough energy to outweigh separated-ion costs.',
 'C6-19':'For identical atoms, halve the bonded or nonbonded separation to get the corresponding radius. The additive model gives rC = 176 − 99 = 77 pm.',
 'C6-20':'Wave diffraction, quantized absorption, penetration, and effective nuclear attraction support the stated claims. Orbitals are probability distributions; discrete energy gaps explain line spectra.',
 'C7-01':'Conductivity needs mobile charge carriers. Metallic electrons and dissolved/molten ions move; ions fixed in a solid lattice do not. Sliding a lattice can juxtapose repelling like charges.',
 'C7-02':'Compare |z₊z₋|/r: MgO has four times the charge product and a smaller separation. The ratio is 4(282/212) = 5.32; forming the lattice reverses the sign.',
 'C7-03':'For the same bonded atom pair, higher bond order means shorter, stronger bonds. Larger halogen radii lengthen S–X bonds; π bonding does not duplicate σ-bond strength.',
 'C7-04':'Compute |ΔEN| as 0.4, 0.9, 1.4, and 1.9. The more electronegative atom is δ⁻; increasing ΔEN increases bond polarity and relative ionic character.',
 'C7-05':'Ten valence electrons give a triple bond and two lone pairs. Formal charge divides shared electrons equally; oxidation numbers assign all C–O bonding electrons to O.',
 'C7-06':'Moving the double bond among three equivalent O positions gives three equivalent forms. Average bond order is (2+1+1)/3; delocalization makes the three bonds equivalent.',
 'C7-07':'Use FC = valence − nonbonding electrons − bond-order sum. A puts −1 on more electronegative O; C has unfavorable charge separation. Unequal contributors require unequal weighting.',
 'C7-08':'Both forms satisfy octets, but A places negative charge on O. Two groups around central N give linear geometry and the sp label in the course model.',
 'C7-09':'Count all neutral valence contributions. An odd total forces an unpaired electron; B can be electron deficient, while second-period N cannot expand its octet.',
 'C7-10':'Changing a P–O single bond to P=O eliminates the +1/−1 formal-charge pair in this expanded-valence drawing. A double bond still counts as one VSEPR group.',
 'C7-11':'Count bonds plus central lone pairs for electron geometry, then omit lone pairs when naming molecular shape. Lone pairs on N and O compress the H–central–H angles.',
 'C7-12':'Five groups give a trigonal bipyramid. Equatorial lone pairs minimize 90° repulsions; only XeF₂ retains two equal opposite bond dipoles that cancel.',
 'C7-13':'Six electron groups give the octahedral parent arrangement. Opposite lone pairs leave a symmetric square plane in XeF₄; the single lone pair in BrF₅ leaves a polar pyramid.',
 'C7-14':'One double and two single bonds occupy three directions. The double bond repels neighboring groups more strongly, expanding O–C–Cl and compressing Cl–C–Cl.',
 'C7-15':'Add bond dipoles as vectors. Identical symmetric surroundings cancel in CO₂ and CCl₄; unlike terminal atoms or substitutions prevent cancellation in COS and CHCl₃.',
 'C7-16':'Each methyl carbon has four groups; carbonyl C and O have three. Count six C–H σ bonds, two C–C σ bonds, and one C–O σ bond; only C=O adds a π bond.',
 'C7-17':'The alkene carbons have three groups and the nitrile atoms two. Each connected pair contributes one σ; the double adds one π and the triple adds two π.',
 'C7-18':'Changed bonds give (614+436) − (347+2×413) = −123 kJ/mol. H₂ supplies 0.150 mol, less than the 0.200 mol ethene; scale heat by that limiting amount.',
 'C8-01':'Self hydrogen bonding needs a donor and an acceptor in the sample. Ether lacks a donor but accepts from water. Ion–dipole orientation puts negative O toward Na⁺.',
 'C8-02':'The molar masses are comparable, so permanent dipoles and especially self hydrogen bonding distinguish the attractions. Stronger attractions raise boiling point and lower same-temperature vapor pressure.',
 'C8-03':'Elongated molecules have more intermolecular contact; larger halogens have more polarizable clouds. Size and contact can outweigh the mere presence of a permanent dipole.',
 'C8-04':'The cis bond dipoles reinforce whereas the trans arrangement cancels them. Boiling changes intermolecular separation without normally breaking C=C or C–Cl covalent bonds.',
 'C8-05':'Use q = (27.02/18.015)×6.01 kJ, then m = q×18.015/40.65 for condensation. Phase-change heat alters the amount of each phase during a fixed-pressure plateau.',
 'C8-06':'Two-phase equilibrium fixes vapor pressure at a given temperature. Doubling headspace requires twice as many vapor moles at that pressure, supplied by evaporation if liquid remains.',
 'C8-07':'Use Kelvin and 38560 J/mol in ln(P₂/P₁) = (ΔHvap/R)(1/T₁−1/T₂). At 55°C the saturation pressure exceeds 250 torr, so the liquid boils under that imposed pressure.',
 'C8-08':'Set P₂ to 450 torr in 1/T₂ = 1/T₁ − (R/ΔHvap)ln(P₂/P₁), then invert and convert to °C. Reaching 760 torr requires a still higher temperature.',
 'C8-09':'Solve the two-point equation for ΔHvap, then use 760 torr for the normal boiling point. The ln(P) versus 1/T slope is −ΔHvap/R.',
 'C8-10':'Lower ambient pressure moves the boiling condition to a lower temperature. The normal point remains defined at 760 torr; fixed-temperature saturation pressure is a property of the substance.',
 'C8-11':'At 1 atm, below the triple pressure, solid CO₂ sublimes. Above both critical coordinates the sample is supercritical; above Tc a distinct liquid cannot be produced by compression alone.',
 'C8-12':'Pressure favors the denser phase. Near ordinary ice–water conditions that phase is liquid, giving the unusual negative solid–liquid boundary slope.',
 'C8-13':'Solid particles vibrate rather than stop. Phase is a homogeneous region, so one pure substance can have two phases. Above Tc the ordinary liquid–gas boundary disappears.',
 'C8-14':'First calculate water saturation pressure, subtract it from total pressure, then use dry H₂ in PV = nRT. The balanced equation gives 1 mol Mg for each mol H₂.'
};
